export function structureLearningCopy(structure,tab,level='university'){
 if(!structure||typeof structure!=='object'||!Object.hasOwn(readingLayers,structure.id))return '';
 if(!['description','function'].includes(tab)||typeof structure[tab]!=='string')return '';
 const original=structure[tab],layers=readingLayers[structure.id];
 if(level==='school')return layers.school[tab];
 if(level==='advanced')return `${original} ${layers.advanced[tab]}`;
 return original;
}
